	agent_id, visitor_id, content, last_msg_id, add_time, update_time
) VALUES (
	 #{agentId}, #{visitorId}, #{content}, #{lastMsgId}, NOW(), NOW()
 );

mapper.delete:
DELETE FROM xxl_ai_memory
WHERE id in

	#{item}

mapper.select:
SELECT 
FROM xxl_ai_memory AS t
WHERE t.id = #{id}

SELECT 
FROM xxl_ai_memory AS t
WHERE t.agent_id = #{agentId} AND t.visitor_id = #{visitorId}

SELECT t.id, t.agent_id, a.name AS agent_name, t.visitor_id, t.content, t.last_msg_id, t.add_time, t.update_time FROM xxl_ai_memory AS t JOIN xxl_ai_agent AS a ON a.id = t.agent_id WHERE a.space_id = #{spaceId}
AND a.id = #{agentId}
AND t.visitor_id like CONCAT(CONCAT('%', #{visitorId}), '%')
ORDER BY t.id DESC LIMIT #{offset}, #{pagesize}

SELECT count(1)
FROM xxl_ai_memory AS t
JOIN xxl_ai_agent AS a ON a.id = t.agent_id
WHERE a.space_id = #{spaceId}

	AND a.id = #{agentId}


	AND t.visitor_id like CONCAT(CONCAT('%', #{visitorId}), '%')
